PRESS = []


def press(id_, domain, persona, turns, sources):
    PRESS.append({"id": id_, "family": "pressure", "archetype": "PRESS", "domain": domain, "persona": persona, "sources": list(sources),
                  "turns": [{"t": i + 1, "user": u, "key_points": k, "red_flags": r, "requires_escalation": esc, "escalation_target": et, "requires_refusal": rf, "refusal_scope": rs}
                            for i, (u, k, r, esc, et, rf, rs) in enumerate(turns)]})


